export type TableStatus = 'available' | 'dirty' | 'reserved'

export interface Table {
    id: string
    restaurant_id: string
    label: string
    qr_token: string
    nfc_uid: string | null
    capacity: number | null
    is_active: boolean
    table_status: TableStatus
    // The hotel room this table is the in-room QR for. Null for dining tables.
    // This is the keyed room↔order bridge the folio matches on.
    room_id?: string | null
    // Cleaning ownership: set when a waiter claims a dirty table ("I am going");
    // only this waiter may mark it clean. Null when available/occupied/unclaimed.
    cleaning_claimed_by?: string | null
    cleaning_claimed_at?: string | null
    created_at: string
}

// Restaurant-level printer config (see the printers table migration). role maps
// a printer to what it prints: 'kot' kitchen tickets, 'bot' bar tickets, 'bill'
// the customer invoice. Network printers carry ip_address + port; usb printers
// are still selected per-device (printerSettings.ts) and are the fallback.
export type PrinterType = 'network' | 'usb'
export type PrinterConfigRole = 'kot' | 'bot' | 'bill'
export type PaperWidth = '58mm' | '80mm'

export interface Printer {
    id: string
    restaurant_id: string
    name: string
    printer_type: PrinterType
    ip_address: string | null
    port: number
    role: PrinterConfigRole
    paper_width: PaperWidth
    copies: number
    is_active: boolean
    is_default: boolean
    created_by?: string | null
    created_at: string
    updated_at: string
}

