export interface Settings {
    id: string
    restaurant_id: string
    theme: {
        primaryColor: string
        secondaryColor: string
        accentColor?: string
        fontFamily: string
        borderRadius: string
        menuLayout: string
    }
    features: {
        tipsEnabled: boolean
        feedbackEnabled: boolean
        geofenceEnabled: boolean
        geofenceRadiusMeters: number
    }
    features_v2: {
        loyaltyEnabled: boolean
        promosEnabled: boolean
        takeoutEnabled: boolean
        // Whether the dine-in/table/QR ordering pathway is offered at all.
        // false for delivery-only operations (Cloud Kitchen) — hides Table
        // Layout nav, the "select your table" customer entry point, and
        // session/waiter dine-in UI. See lib/businessMode.ts.
        dineInEnabled: boolean
        multiLanguageEnabled: boolean
        serviceRequestsEnabled: boolean
        splitBillingEnabled: boolean
        dynamicPricingEnabled: boolean
        ingredientTrackingEnabled: boolean
        staffShiftsEnabled: boolean
        feedbackEnabled: boolean
        // Customers can request a waiter to open their table session (Phase 3)
        selfOrderRequestEnabled?: boolean
        // When true, a waiter must open a table session before guests can order.
        // When false/undefined (default), sessions auto-open on QR scan (self-service).
        waiterSessionEnabled?: boolean
        // When true (Mode 2 / low plans), placed dine-in orders wait for a waiter to
        // confirm before the kitchen sees them; stock is deducted on confirm. When
        // false (Mode 1 / premium), orders go straight to the kitchen at placement.
        waiterOrderConfirmation?: boolean
        // Manager-configured one-tap "quick serve" items a customer can request
        // (water, cold drink, tissue…). Each request goes to the waiter feed.
        quickServeItems?: string[]
        defaultTaxRate: number
        currency: string
        currencySymbol: string
        // Nepal-specific
        nepalPayEnabled: boolean
        vatEnabled: boolean
        serviceChargeEnabled?: boolean
        serviceChargeRate?: number
        phoneOtpEnabled: boolean
        /**
         * @deprecated Superseded by the per-user calendar toggle (the
         * kkkhane-calendar cookie, see lib/calendar.ts). Bikram Sambat now
         * leads by default for everyone and each user flips their own
         * preference, so nothing reads this. Kept so stored settings rows
         * still parse; safe to drop in a later migration.
         */
        bsDateEnabled: boolean
        // Notification
        notificationSoundUrl?: string | null
        financeEnabled?: boolean
        // In-room service: when true, a hotel room's QR requires the guest to
        // confirm the phone on their booking, then surfaces a "Call for Service"
        // tel: button to the reception number below. Off = today's self-service.
        roomServiceCallEnabled?: boolean
        // Reception / room-service phone the "Call for Service" button dials.
        receptionPhone?: string | null
        printInvoiceEnabled?: boolean
        generateInvoiceEnabled?: boolean
        staffManagementEnabled?: boolean
        tableManagementEnabled?: boolean
        irdSyncEnabled?: boolean
        manualEntryEnabled?: boolean
        printBillEnabled?: boolean
        showInvoiceEnabled?: boolean
        kotEnabled?: boolean
        kdsEnabled?: boolean
        roomServiceChargeEnabled?: boolean
        roomServiceChargeRooms?: string[]
    }
    business_hours: BusinessHours | null
    updated_at: string
}

// Per-day opening hours. Keys are lowercase weekday names (monday…sunday).
export interface DayHours {
    open: string   // "HH:MM" 24h
    close: string  // "HH:MM" 24h
    closed: boolean
}
export type BusinessHours = Record<string, DayHours>

